mapper.select:
SELECT COALESCE(SUM(mu.total_tokens), 0)
FROM ai_model_usage mu
INNER JOIN ai_run_trace trace ON trace.run_id = mu.run_id
WHERE trace.tenant_id = #{tenantId}
  AND mu.user_id IS NOT NULL
  AND mu.user_id != ''
  AND mu.created_at  >=  #{startTime}
  AND mu.created_at  <  #{endTime}

SELECT COUNT(*)
FROM ai_run_trace
WHERE tenant_id = #{tenantId}
  AND question IS NOT NULL
  AND TRIM(question) != ''
  AND created_at  >=  #{startTime}
  AND created_at  <  #{endTime}

SELECT * FROM ( SELECT CONCAT('ALERT-', id) AS id, 'ALERT' AS sourceType, COALESCE(NULLIF(workflow_name, ''), NULLIF(rule_name, ''), '系统告警') AS sourceName, severity, status, error_code AS errorCode, COALESCE(NULLIF(error_message, ''), '系统检测到需要处理的运行异常') AS errorMessage, last_occurred_at AS occurredAt, '/knowledge/alerts' AS targetPath FROM ai_alert_record WHERE status IN ('OPEN', 'ACKNOWLEDGED') AND last_occurred_at >= #{startTime} AND last_occurred_at < #{endTime}
UNION ALL
SELECT CONCAT('WORKFLOW-', workflow_run.id) AS id, 'WORKFLOW' AS sourceType, COALESCE( NULLIF(workflow_run.workflow_name, ''), workflow_run.workflow_code, '工作流' ) AS sourceName, 'ERROR' AS severity, workflow_run.status, workflow_run.error_code AS errorCode, '工作流运行失败，请进入运行详情查看安全错误信息' AS errorMessage, COALESCE(workflow_run.finished_at, workflow_run.created_at) AS occurredAt, CONCAT('/knowledge/workflow-runs/detail/', workflow_run.run_id) AS targetPath FROM ai_workflow_run workflow_run INNER JOIN ai_run_trace trace ON trace.run_id = workflow_run.agent_run_id WHERE workflow_run.status = 'FAILED' AND trace.tenant_id = #{tenantId} AND workflow_run.created_at >= #{startTime} AND workflow_run.created_at < #{endTime}
UNION ALL
SELECT CONCAT('MODEL-', mu.id) AS id, 'MODEL' AS sourceType, COALESCE( NULLIF(mu.model_name, ''), NULLIF(mu.model_code, ''), '模型服务' ) AS sourceName, 'ERROR' AS severity, 'FAILED' AS status, COALESCE(NULLIF(mu.error_category, ''), 'UNKNOWN') AS errorCode, '模型调用失败，请进入模型配置查看连接状态' AS errorMessage, mu.created_at AS occurredAt, '/knowledge/system-config' AS targetPath FROM ai_model_usage mu INNER JOIN ai_run_trace trace ON trace.run_id = mu.run_id WHERE mu.success = 0 AND trace.tenant_id = #{tenantId} AND mu.created_at >= #{startTime} AND mu.created_at < #{endTime} UNION ALL SELECT CONCAT('KNOWLEDGE-', id) AS id, 'KNOWLEDGE' AS sourceType, CONCAT('向量任务 #', id) AS sourceName, 'ERROR' AS severity, status, 'VECTOR_TASK_FAILED' AS errorCode, '知识库向量任务失败，请进入向量任务监控查看详情' AS errorMessage, COALESCE(finished_at, updated_at) AS occurredAt, '/knowledge/vector-task' AS targetPath FROM knowledge_base_vector_task WHERE status = 'FAILED' AND document_id IN ( SELECT id FROM knowledge_document WHERE tenant_id = #{tenantId} ) AND updated_at >= #{startTime} AND updated_at < #{endTime} ) issue ORDER BY occurredAt DESC LIMIT #{limit}
